// Builds the color-model fixture shared by the Node and Python tests.
import { dilutionRGB, labOf } from '../../src/problems/color-model.js';
import { getProblem, instantiate } from '../../src/problems/index.js';

export const WATER_POINTS = [0, 0.5, 1, 2, 3.7, 5, 8, 10, 11, 12.5, 15, 20, 25, 30];

export function colorModelFixture() {
  const p = instantiate(getProblem('dilution'));
  return {
    note: 'Generated by scripts/export-fixtures.mjs from src/problems/color-model.js and dilution.js. Do not edit.',
    points: WATER_POINTS.map((water) => ({
      water,
      rgb: dilutionRGB(water),
      lab: labOf(dilutionRGB(water)),
      deltaE: p.evaluate([water]),
    })),
  };
}
